entries[33976] = { ["name"] = "Braufestwidder", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Braufestwidder oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Brauer haben den offiziellen Handel mit diesen Reittieren beendet, als ihnen vorgeworfen wurde, dass sie \"zu temperamentvoll\" wären, um in Städten geritten zu werden.\"\nKlassisch" }
entries[33977] = { ["name"] = "Schneller Braufestwidder", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schnellen Braufestwidder oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Zwerge behaupten, die ausgeglichene Stimmung dieser Spezies entsteht durch strenge Ausbildung, doch andere Völker sind der Meinung, dass auch die tägliche Versorgung mit Starkbier etwas damit zu tun haben könnte.\"\nBeute von:\nFassförmige Schatzkiste\nFeiertag:\nBraufest" }
