entries[34060] = { ["name"] = "Flugmaschine", ["text"] = "Reittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört eine Flugmaschine oder gibt sie wieder frei. Benötigt 1 Fertigkeitspunkt in der Ingenieurskunst der Scherbenwelt. Diese Flugmaschine passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Ingenieurskunst der Scherbenwelt (1)\nBenötigt Unerfahrenes Reiten\n\n\"Das Rückgrat der Luftstreitkräfte der Allianz besteht aufgrund ihrer Manövrierfähigkeit und Geschwindigkeit größtenteils aus gnomischen Flugmaschinen.\"\nBeruf:\nIngenieurskunst" }
entries[34061] = { ["name"] = "Turbogetriebene Flugmaschine", ["text"] = "Reittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört eine turbogetriebene Flugmaschine oder gibt sie wieder frei. Benötigt 75 Fertigkeitspunkte in der Ingenieurskunst der Scherbenwelt. Diese Flugmaschine passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Ingenieurskunst der Scherbenwelt (75)\nBenötigt Unerfahrenes Reiten\n\n\"Nur die talentiertesten Ingenieure verfügen über den Mut und die geistige Ausdauer, um eine Flugmaschine zu bauen, die derartige Stabilität und Sicherheit bietet. Sie mit einem Turbo anzutreiben, ist einfach nur Irrsinn!\"\nBeruf:\nIngenieurskunst" }
