entries[34248] = { ["name"] = "Phasenvorrichtung von Bash'ir", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Versetzt den Charakter, seine Gruppe und ihre Begleiter in einen phasenverschobenen Zustand, in dem sie für nicht phasenverschobene Kreaturen unsichtbar sind und eingeschmuggelte Manazellen beim Landeplatz von Bash'ir sehen können. Alle Gruppenmitglieder müssen sich innerhalb von 100 Metern um den Zaubernden befinden, um den phasenverschobenen Zustand aufrechtzuerhalten. Funktioniert nur auf dem Landeplatz von Bash'ir.\n\"Alles oder nichts...\"" }
