entries[34481] = { ["name"] = "Rezept: Trank des verrückten Alchemisten", ["text"] = "Benutzen:\nBenötigt Alchemie der Scherbenwelt\n(25)\nBenötigt Expedition des Cenarius\n- Freundlich\nVerkaufspreis:\nTrank des verrückten Alchemisten\nBenutzen: Stellt 625 Mana und Gesundheit wieder her. Hat gelegentlich Nebeneffekte. (5 Min Abklingzeit)\nBenötigt Alchemie der Scherbenwelt\n(15)\nVerkaufspreis:\nBenötigt Kristallphiole , Zottelkappe (2)" }
