entries[34484] = { ["name"] = "Alter Eisenkiefer", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+4 Intelligenz\n+2 Ausdauer\n\"Der legendäre, unfangbare Fisch von Eisenschmiede. Allein dieses alte, schuppige Monster in Euren Händen zu halten, verleiht Euch ein Gefühl von Stärke.\"\nVerkaufspreis:" }
