entries[35225] = { ["name"] = "X-51 Netherrakete", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nEine Reitrakete! Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ursprünglich als Beschleunigung für eine deutlich größere Rakete entwickelt, ermöglicht die X-51 den bestmöglichen Schub für einen einzelnen Passagier.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
